<?php require_once __DIR__.'/../config/database.php';header('Content-Type: application/json');$s=strtoupper(trim($_GET['symbol']??''));if(!preg_match('/^[A-Z0-9.\-^=]{1,20}$/',$s)){http_response_code(400);exit(json_encode(['error'=>'Invalid ticker']));}$q=db()->prepare('SELECT s.ticker,s.company_name,s.exchange,p.date,p.open,p.high,p.low,p.close,p.adjusted_close,p.volume FROM stocks s LEFT JOIN prices p ON p.stock_id=s.id WHERE s.ticker=? ORDER BY p.date DESC LIMIT 1');$q->execute([$s]);echo json_encode($q->fetch()?:['error'=>'No cached data']);